-- ======================================================================
-- PEL·LÍCULES
-- ======================================================================
INSERT INTO pelicula (imdb_id, nom, duracio, sinopsi, classificacio, url_trailer, valoracio, any_estrena) VALUES
  ('tt0111161', 'Cadena perpètua', 142, 'Un banquer condemnat injustament per assassinat forja una amistat duradora a la presó i manté viva l''esperança durant dècades.', '+16', 'https://trailers.cinereserva.example/tt0111161', 9.3, 1994),
  ('tt0068646', 'El Padrí', 175, 'La història d''una poderosa família de la màfia italoamericana quan el patriarca passa el relleu al seu fill més reticent.', '+16', 'https://trailers.cinereserva.example/tt0068646', 9.2, 1972),
  ('tt0468569', 'El cavaller fosc', 152, 'Batman s''enfronta al Joker, un criminal caòtic que sumeix Gotham en el pànic i posa a prova els límits de l''heroi.', '+12', 'https://trailers.cinereserva.example/tt0468569', 9.0, 2008),
  ('tt0137523', 'El club de la lluita', 139, 'Un oficinista insomne i un carismàtic venedor de sabó funden un club de lluita clandestí que es descontrola.', '+18', 'https://trailers.cinereserva.example/tt0137523', 8.8, 1999),
  ('tt0109830', 'Forrest Gump', 142, 'Un home de gran bondat travessa dècades de la història nord-americana mentre persegueix el seu gran amor.', '+12', 'https://trailers.cinereserva.example/tt0109830', 8.8, 1994),
  ('tt1375666', 'Origen', 148, 'Un lladre especialitzat en infiltrar-se als somnis rep l''encàrrec impossible d''implantar una idea a la ment d''algú.', '+12', 'https://trailers.cinereserva.example/tt1375666', 8.8, 2010),
  ('tt0133093', 'Matrix', 136, 'Un programador descobreix que la realitat és una simulació i s''uneix a la rebel·lió contra les màquines.', '+16', 'https://trailers.cinereserva.example/tt0133093', 8.7, 1999),
  ('tt0110912', 'Pulp Fiction', 154, 'Diverses històries de criminals de Los Angeles s''entrellacen en un mosaic d''humor negre i violència.', '+18', 'https://trailers.cinereserva.example/tt0110912', 8.9, 1994),
  ('tt0120737', 'El Senyor dels Anells: La Comunitat de l''Anell', 178, 'Un jove hòbbit emprèn un viatge perillós amb una colla d''aliats per destruir un anell que pot dominar el món.', '+12', 'https://trailers.cinereserva.example/tt0120737', 8.9, 2001),
  ('tt0816692', 'Interstellar', 169, 'Un grup d''astronautes travessa un forat de cuc a la recerca d''un nou planeta per salvar la humanitat.', '+12', 'https://trailers.cinereserva.example/tt0816692', 8.7, 2014),
  ('tt0245429', 'El viatge de Chihiro', 125, 'Una nena queda atrapada en un món d''esperits i ha de treballar en una casa de banys per rescatar els seus pares.', '+7', 'https://trailers.cinereserva.example/tt0245429', 8.6, 2001),
  ('tt0114369', 'Seven', 127, 'Dos detectius persegueixen un assassí en sèrie que basa els seus crims en els set pecats capitals.', '+18', 'https://trailers.cinereserva.example/tt0114369', 8.6, 1995),
  ('tt0102926', 'El silenci dels anyells', 118, 'Una jove agent de l''FBI demana ajuda a un brillant psiquiatre caníbal per atrapar un altre assassí.', '+18', 'https://trailers.cinereserva.example/tt0102926', 8.6, 1991),
  ('tt0076759', 'La guerra de les galàxies', 121, 'Un jove granger s''uneix a una princesa rebel i un contrabandista per lluitar contra un imperi galàctic.', 'TP', 'https://trailers.cinereserva.example/tt0076759', 8.6, 1977),
  ('tt0088763', 'Retorn al futur', 116, 'Un adolescent viatja per error als anys cinquanta i ha d''assegurar-se que els seus pares s''enamorin.', '+7', 'https://trailers.cinereserva.example/tt0088763', 8.5, 1985),
  ('tt0083658', 'Blade Runner', 117, 'En un Los Angeles distòpic, un caçador de replicants rastreja quatre androides fugitius.', '+16', 'https://trailers.cinereserva.example/tt0083658', 8.1, 1982),
  ('tt1049413', 'Up', 96, 'Un vidu gran lliga milers de globus a casa seva per complir un vell somni, acompanyat d''un nen inesperat.', 'TP', 'https://trailers.cinereserva.example/tt1049413', 8.3, 2009),
  ('tt0114709', 'Toy Story', 81, 'Les joguines d''un nen cobren vida quan ell no hi és, i un cowboy veu perillar el seu lloc amb l''arribada d''un astronauta.', 'TP', 'https://trailers.cinereserva.example/tt0114709', 8.3, 1995),
  ('tt0172495', 'Gladiator', 155, 'Un general romà traït es converteix en gladiador i busca venjança contra l''emperador corrupte.', '+16', 'https://trailers.cinereserva.example/tt0172495', 8.5, 2000),
  ('tt0482571', 'El truc final', 130, 'Dos il·lusionistes rivals s''obsessionen amb superar-se mútuament fins a arribar a extrems perillosos.', '+12', 'https://trailers.cinereserva.example/tt0482571', 8.5, 2006),
  ('tt0095765', 'Cinema Paradiso', 155, 'Un cineasta recorda la seva infantesa en un poble sicilià i l''amistat amb el projeccionista del cinema local.', '+12', 'https://trailers.cinereserva.example/tt0095765', 8.5, 1988),
  ('tt0457430', 'El laberint del Fauno', 118, 'A la postguerra espanyola, una nena descobreix un laberint fantàstic mentre la realitat que l''envolta és cruel.', '+16', 'https://trailers.cinereserva.example/tt0457430', 8.2, 2006),
  ('tt0211915', 'Amélie', 122, 'Una tímida cambrera de Montmartre decideix millorar en secret la vida de la gent del seu voltant.', '+16', 'https://trailers.cinereserva.example/tt0211915', 8.3, 2001),
  ('tt2582802', 'Whiplash', 106, 'Un jove bateria entra en un conservatori exigent i es veu sotmès a un professor despietat.', '+16', 'https://trailers.cinereserva.example/tt2582802', 8.5, 2014),
  ('tt1675434', 'Intocable', 112, 'Un aristòcrata tetraplègic contracta com a cuidador un jove dels suburbis, i neix una amistat improbable.', '+12', 'https://trailers.cinereserva.example/tt1675434', 8.5, 2011),
  ('tt2380307', 'Coco', 105, 'Un nen mexicà que somia ser músic viatja al món dels morts per descobrir el secret de la seva família.', 'TP', 'https://trailers.cinereserva.example/tt2380307', 8.4, 2017),
  ('tt0317248', 'Ciutat de Déu', 130, 'Dos nois creixen en una favela de Rio de Janeiro i prenen camins oposats entre la fotografia i el crim.', '+18', 'https://trailers.cinereserva.example/tt0317248', 8.6, 2002),
  ('tt0338013', 'Eternal Sunshine of the Spotless Mind', 108, 'Una parella decideix esborrar-se els records l''un de l''altre mitjançant un procediment experimental.', '+16', 'https://trailers.cinereserva.example/tt0338013', 8.3, 2004);

